import{z as B,x as s,o as l,c as d,q as r,j as i,D as A,d as e,s as t,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const R=JSON.parse('{"title":"语言混杂","description":"","frontmatter":{"title":"语言混杂","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/language-mixing-reasoning.md","filePath":"llm/language-mixing-reasoning.md","lastUpdated":1791413859000}'),p={name:"llm/language-mixing-reasoning.md"};function D(m,a,u,h,F,g){const n=s("Mermaid");return l(),d("div",null,[a[2]||(a[2]=r('<h1 id="语言混杂" tabindex="-1">语言混杂 <a class="header-anchor" href="#语言混杂" aria-label="Permalink to &quot;语言混杂&quot;">​</a></h1><div class="epigraph"><p>R1-Zero 在中英之间来回切：对校验器无成本，对用户不可读；冷启动 SFT 要把语言当格式约束补回去。</p><footer>—— DeepSeek-AI R1 对 R1-Zero 可读性与语言混合问题的修复路径</footer></div><p><a href="/llm/aha-moment">上一课</a>的探索相变会一并强化「碰巧常赢」的表面形式。缺口是：<strong>校验器只看最终答案，链的语言不进 \\(R\\)，于是中英夹杂、语码转换成为无成本的工作记忆。</strong> R1 用冷启动可读长链 + 多阶段训练修复。本课写混杂的原因与约束，接到忠实性：可读 ≠ 忠实。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>基座多语言。数学符号与英文术语在预训练里与中文叙述混排。RL 只奖 boxed 数字，混杂不降 \\(R\\)，有时还升（某些英文推理片段更常对）。产品要求单一语言或用户语言。这是多目标里漏掉的轴：语言一致性。</p><p><span class="marginnote">术语翻译：「语码转换」（code-switching）就是同一句话或同一思考中途切换语言，比如「这个 bound 我们用 Cauchy-Schwarz 放缩一下」。它在这里不算 bug 级错误——符号和术语本来就该保留原文——问题在于整段叙述性推理也跟着乱切，用户读起来像乱码。</span></p><p>R1-Zero 跳过 SFT，没有「用用户语言写思维」的示范，混杂更重。R1 冷启动先示范可读链，再 RL，混杂下降。代价是探索可能变窄。数学符号、变量名、代码标识符不应计入「外语」；语码转换统计要排除公式环境，否则会把合法证明当混杂。</p><h3 id="不要用语言识别当主奖励" tabindex="-1">不要用语言识别当主奖励 <a class="header-anchor" href="#不要用语言识别当主奖励" aria-label="Permalink to &quot;不要用语言识别当主奖励&quot;">​</a></h3><p>重罚混杂会让模型为了语言牺牲搜索，难题准确率掉。应：格式轻约束 + 示范，金标仍是对错。与过长惩罚一样，权重按产品扫。</p><p><span class="marginnote">思维对用户隐藏时，混杂仍影响监视器可读性（monitorability）。内部链也需要语言政策。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>测量：语码转换次数、主语言占比、用户语言一致率。训练：冷启动 SFT 锁语言；RL 加轻量语言一致项或约束解码（不允许切语言——可能伤数学符号，要白名单）。评测：准确率与可读性分表。蒸馏学生：教师链若混杂，学生会学混杂，过滤或改写教师链。</p>',12)),(l(),i(o,null,{default:A(()=>[t(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20R0%5B%22R1-Zero%EF%BC%9A%E5%8F%AA%E5%A5%96%E5%AF%B9%E9%94%99%22%5D%20--%3E%20MIX%5B%22%E9%93%BE%E4%B8%8A%E8%AF%AD%E8%A8%80%E6%B7%B7%E6%9D%82%22%5D%0A%20%20CS%5B%22%E5%86%B7%E5%90%AF%E5%8A%A8%E5%8F%AF%E8%AF%BB%E9%95%BF%E9%93%BE%22%5D%20--%3E%20R1%5B%22%E5%86%8D%20RL%22%5D%0A%20%20R1%20--%3E%20READ%5B%22%E5%8F%AF%E8%AF%BB%E6%80%A7%E5%9B%9E%E5%8D%87%22%5D%0A%20%20LANG%5B%22%E8%BF%87%E5%BC%BA%E8%AF%AD%E8%A8%80%E6%83%A9%E7%BD%9A%22%5D%20--%3E%20DROP%5B%22%E9%9A%BE%E9%A2%98%E5%87%86%E7%A1%AE%E7%8E%87%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与混合思考：短模式更易保持用户语言；思维模式是重灾区。分模式约束。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},[e("数字实例：怎么量混杂？设一条 500 字的推理链，中文字符 300、英文叙述字符 200，主语言占比就是 \\(300/500=60\\%\\)；若这条链里有 7 处「整句换语言」的切换点，语码转换次数就是 7。公式环境（LaTeX、代码块）要先用白名单剔除再统计，否则一个 "),E("code",null,"x^2 + y^2"),e(" 就被当成一次切换。")])],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"无成本维度会被 RL 当工作记忆用。语言、标记符号、重复填充都是候选。约束哪个，取决于产品与监视。完全不约束，监视和摘要器失败。约束过死，回到短 SFT 分布，aha / 回溯减少。R1 的多阶段是折中，不是定理。",-1)),(l(),i(o,null,{default:A(()=>[t(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22RL%20%E5%8F%AA%E5%A5%96%E6%9C%80%E7%BB%88%E7%AD%94%E6%A1%88%E5%AF%B9%E9%94%99%22%5D%20--%3E%20B%5B%22%E9%93%BE%E7%9A%84%E5%BD%A2%E5%BC%8F%E6%97%A0%E6%88%90%E6%9C%AC%22%5D%0A%20%20B%20--%3E%20C1%5B%22%E5%AE%8C%E5%85%A8%E4%B8%8D%E7%BA%A6%E6%9D%9F%E8%AF%AD%E8%A8%80%22%5D%0A%20%20C1%20--%3E%20D1%5B%22%E6%B7%B7%E6%9D%82%E6%88%90%E7%81%BE%2C%E7%9B%91%E8%A7%86%E5%99%A8%E8%AF%BB%E4%B8%8D%E6%87%82%E9%93%BE%22%5D%0A%20%20B%20--%3E%20C2%5B%22%E9%87%8D%E7%BD%9A%E8%AF%AD%E8%A8%80%E5%88%87%E6%8D%A2%22%5D%0A%20%20C2%20--%3E%20D2%5B%22%E6%A8%A1%E5%9E%8B%E4%B8%BA%E8%AF%AD%E8%A8%80%E7%89%BA%E7%89%B2%E6%90%9C%E7%B4%A2%2C%E9%9A%BE%E9%A2%98%E6%8E%89%E5%88%86%22%5D%0A%20%20B%20--%3E%20C3%5B%22%E5%86%B7%E5%90%AF%E5%8A%A8%E7%A4%BA%E8%8C%83%20%2B%20%E8%BD%BB%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20C3%20--%3E%20D3%5B%22%E5%8F%AF%E8%AF%BB%E6%80%A7%E5%9B%9E%E5%8D%87%2C%E6%8E%A2%E7%B4%A2%E4%BF%9D%E7%95%99%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">直觉类比：监考老师只收答案卡、不看草稿纸，学生草稿纸上就会越写越潦草、中英夹杂、画满只有自己懂的符号——反正没人看。链上语言混杂就是这堆草稿：奖励不给它定价，它就会漂到最省事的状态。想让它整洁，要么换更认真的学生（冷启动示范），要么轻微扣卷面分（轻约束），而不是没收草稿纸（重罚）。</span></p><p><span class="marginnote">「用户用中文问、答案中文、思维英文」有时是可接受的内部政策，但必须声明，不能当意外。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>纯英文题库上混杂不明显，不代表多语言部署安全。本课对中文产品尤其硬。语码统计要排除公式与代码；语言轻约束加冷启动可以，重罚会打压搜索；内部链语言仍影响监视可读性。下一课忠实性：即使用户语言干净，链仍可能不对应内部计算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>语言混杂因校验器不给语言定价而出现；探索相变会放大它。</li><li>冷启动可读示范 + 轻约束，优于重罚语言。</li><li>内部链语言政策影响监视，不只影响 UI。</li><li>蒸馏会复制教师混杂，需过滤。</li><li>出处：DeepSeek-AI R1 对 Zero 混语言与冷启动修复的报告。</li></ul>',6))])}const c=B(p,[["render",D]]);export{R as __pageData,c as default};
